// Threat Model Guard: NEVER let LLM make free-text halal claims.
// Use regex/heuristics or structured schema to extract search parameters only.
const query = ($json.body.message || $json.body.query || '').toLowerCase();

let country = 'JP';
let city = 'Tokyo';
let cuisine = 'Ramen';
let filter = 'halal';

if (query.includes('singapore') || query.includes('singapura')) { country = 'SG'; city = 'Singapore'; }
else if (query.includes('saudi') || query.includes('mecca') || query.includes('madinah')) { country = 'SA'; city = 'Mecca'; }
else if (query.includes('london') || query.includes('uk') || query.includes('inggris')) { country = 'GB'; city = 'London'; }
else if (query.includes('china') || query.includes('beijing') || query.includes('shanghai')) { country = 'CN'; city = 'Beijing'; }

if (query.includes('yakiniku')) cuisine = 'Yakiniku';
else if (query.includes('soba') || query.includes('udon')) cuisine = 'Soba';
else if (query.includes('sushi')) cuisine = 'Sushi';

return {
  json: {
    sender: $json.body.sender || 'traveler',
    originalQuery: query,
    country,
    city,
    cuisine,
    filter
  }
};

const items = $json.items || [];
const topPlace = items[0];

let reply = 'Maaf, tidak ditemukan tempat makan yang memenuhi kriteria fail-closed halal di area tersebut.';

if (topPlace) {
  reply = `Rekomendasi Kuliner Terverifikasi:\n` +
    `• ${topPlace.name} (${topPlace.cuisine})\n` +
    `• Status: ${topPlace.tier} [Terverifikasi ${topPlace.certifierName || 'Resmi'}]\n` +
    `• Kisaran Harga: ${topPlace.priceRange?.formattedLocalRange || '¥1,000–2,000'} (≈ ${topPlace.priceRange?.formattedIdrRange || 'Rp 104.500–209.000'})\n` +
    `• Alamat: ${topPlace.address}\n\n` +
    `[Data Footprint: ~1.8 MB | Kuota roaming dioptimalkan]`;
}

return {
  json: {
    status: 'SUCCESS',
    reply,
    candidateCount: items.length,
    dataFootprint: '~1.8 MB'
  }
};
